  toolbar.insertAdjacentHTML('beforeend',html`<label class="visually-hidden" for="sheets-font-family">Font family</label><select id="sheets-font-family" data-font-input aria-label="Font family">${FORMAT_FONTS.map(font=>html`<option value="${font}">${font}</option>`)}</select><label class="visually-hidden" for="sheets-font-value">Font size</label><input id="sheets-font-value" data-size-input type="number" min="6" max="96" value="13" aria-label="Font size">`.toString());
