  toolbar.insertAdjacentHTML('beforeend',html`<span class="sheets-sep" aria-hidden="true"></span>${tool('font-smaller','Decrease font size','minus')}${tool('font-larger','Increase font size','plus')}${tool('merge-cells','Merge cells','merge')}${tool('wrap-on','Wrap text','wrap')}${tool('rotation-custom','Text rotation','rotate')}${tool('insert-link','Insert link','link')}${tool('cell-comments','Comment','comment')}${tool('chart-preview','Insert chart','chart')}`.toString());
  for(const [action,icon]of Object.entries({undo:'undo',redo:'redo',bold:'bold',italic:'italic',underline:'underline',strike:'strike','align-left':'align-left','align-center':'align-center','align-right':'align-right',filter:'filter'})){const button=toolbar.querySelector('[data-action="'+action+'"]');if(button)button.innerHTML=sheetIcon(icon)}
